from common import *
def run():
    bio = [
     mcq("Which of the following correctly matches a cell organelle with its function?", ["Ribosome – digestion of worn-out organelles", "Lysosome – synthesis of proteins", "Golgi apparatus – packaging and dispatch of materials", "Mitochondria – photosynthesis"], 'c', "Golgi apparatus packages and dispatches materials; the others are mismatched."),
     mcq("A wilted lettuce leaf becomes crisp when it is kept in tap water. This is because:", ["minerals diffuse out of the cells", "the cell walls dissolve in water", "water leaves the cells by osmosis", "water enters the cells by osmosis and makes them turgid"], 'd', "Tap water is hypotonic to the cell sap, so water enters by osmosis and the cells become turgid."),
     mcq("Leaves and stems of a canna plant bend easily without breaking. The tissue that provides this flexibility is:", ["parenchyma", "collenchyma", "sclerenchyma", "xylem"], 'b', "Collenchyma gives flexibility along with mechanical support."),
     mcq("Blood is classified as a connective tissue because it:", ["flows inside blood vessels", "has a fluid matrix (plasma) and connects different parts of the body by transporting substances", "contains haemoglobin", "contains cells"], 'b', "Connective tissue has cells in a matrix; blood’s matrix is plasma and it links organs by transport."),
     mcq("Which substances released from old refrigerators, air-conditioners and aerosol sprays damage the ozone layer?", ["Carbon monoxide", "Chlorofluorocarbons (CFCs)", "Methane", "Nitrogen"], 'b', "CFCs release chlorine atoms in the stratosphere that break down ozone."),
     mcq("Mushrooms and moulds are placed in kingdom Fungi because they:", ["make food by photosynthesis", "are prokaryotes", "have chitin in their cell wall and absorb food from dead organic matter", "are motile and ingest food"], 'c', "Fungi are heterotrophic, saprotrophic, with chitinous cell walls."),
     mcq("Which part of a flower develops into the fruit after fertilisation?", ["Ovule", "Ovary", "Stigma", "Anther"], 'b', "The ovary becomes the fruit and ovules become seeds."),
     ar("Tendons are strong but have very little elasticity.", "Tendons attach muscles to bones.", 'b', "Both are true, but attachment of muscle to bone does not explain their low elasticity."),
     ar("An increase in the amount of carbon dioxide in the atmosphere raises the temperature of the Earth.", "Carbon dioxide absorbs outgoing infrared radiation and re-radiates part of it back to the Earth.", 'a', "R is the mechanism behind the greenhouse effect described in A."),
     OR(sa("Write any two differences between self-pollination and cross-pollination.", 2, "Self: pollen transferred to stigma of the same flower/plant; no genetic variation [1]. Cross: pollen transferred to stigma of another flower of a different plant; variation produced; agent needed. [1]"),
        sa("Name two agents of pollination and give one plant pollinated by each.", 2, "Wind – maize/wheat; insects/bees – sunflower/mustard; birds/water also accepted. [1 + 1]")),
     OR(sa("Name the kingdom to which each of the following belongs and write one distinguishing feature: (i) <i>Amoeba</i> (ii) mushroom (iii) mango tree.", 3, "(i) Protista – unicellular eukaryote [1] (ii) Fungi – heterotrophic, chitin cell wall [1] (iii) Plantae – multicellular autotroph with cellulose wall [1]"),
        sa("Differentiate between monocots and dicots on any three points, with one example each.", 3, "Seed leaves: one/two; Leaf venation: parallel/reticulate; Roots: fibrous/tap root; flower parts in 3s/4–5s. Example: wheat/maize; gram/pea. [Any three differences 3 × 1; examples as support]")),
     sa("The figure shows the same plant cell kept in three different solutions X, Y and Z. State whether each solution is hypotonic, isotonic or hypertonic to the cell sap. Also name the phenomenon observed in the cell Z.", 3, "X – hypotonic [1]; Y – isotonic [1]; Z – hypertonic, plasmolysis [1]", fig=plasmo_fig()),
     sa("Fill in the blanks of the table:" + table(['Tissue', 'Location', 'Function'], [['Phloem', 'Vascular bundles of plants', '(a) ________'], ['(b) ________', 'Wall of the heart', 'Rhythmic contraction to pump blood'], ['Areolar tissue', '(c) ________', 'Supports internal organs and helps in repair']]), 3, "(a) Transport of food (sugars) from leaves to other parts [1] (b) Cardiac muscle [1] (c) Between skin and muscles / around blood vessels and nerves / in the spaces inside organs [1]"),
     sa("The figure shows three types of muscle fibres X, Y and Z. Identify each and name one place in the human body where it is found.", 3, "X – skeletal (striated) muscle: limbs/biceps [1]; Y – smooth (unstriated) muscle: wall of stomach/intestine/blood vessels [1]; Z – cardiac muscle: heart [1]", fig=row(muscle_fig('striated'), muscle_fig('smooth'), muscle_fig('cardiac'), labels=['X', 'Y', 'Z'])),
     case("While playing football, Ravi twisted his ankle badly. The doctor said that a ligament was torn and advised rest. Ravi’s teacher later explained that ligaments help the joints work, and that the human body has different types of joints such as those at the knee, shoulder and neck.",
          [sub("What is a ligament? State its function.", 1, "A strong, flexible connective tissue joining one bone to another; it holds bones in position at a joint. [1]"),
           sub("Name the type of joint present at the knee.", 1, "Hinge joint. [1]"),
           OR(sub("Differentiate between a tendon and a ligament (any two points).", 2, "Tendon connects muscle to bone, inelastic, strong; ligament connects bone to bone, elastic/flexible. [1 + 1]"),
              sub("Name the type of joint at the (i) shoulder and (ii) neck (skull–vertebra). State one movement each permits.", 2, "(i) Ball-and-socket – rotation in all directions [1] (ii) Pivot joint – side to side/nodding movement [1]"))], lab='alpha'),
     OR(sa("(i) State the three main postulates of the cell theory.<br>(ii) Name the scientist who first observed cells and the material he used.", 5, "(i) All living organisms are made of cells; the cell is the basic unit of life; all cells arise from pre-existing cells. [3] (ii) Robert Hooke [1], thin slice of cork [1]"),
        sa("Distinguish between a plant cell and an animal cell on any five points.", 5, "Cell wall present/absent; chloroplasts present/absent; large central vacuole/small or absent; centrioles absent/present; shape fixed/irregular, etc. [5 × 1]")),
    ]
    chem = [
     mcq("A mixture of acetone (boiling point 56 °C) and water (boiling point 100 °C) can best be separated by:", ["filtration", "simple distillation", "using a separating funnel", "centrifugation"], 'b', "Miscible liquids with sufficiently different boiling points are separated by distillation."),
     mcq("The percentage by mass of oxygen in calcium carbonate, CaCO<sub>3</sub> (Ca = 40, C = 12, O = 16), is:", ["12 %", "40 %", "48 %", "60 %"], 'c', "Formula mass = 100 u; oxygen = 48 u → 48 %."),
     mcq("Which of the following best describes a scientific model?", ["An exact full-size copy of a system", "A simplified representation used to explain or predict the behaviour of a system", "A final, never-changing truth", "A guess that is never tested"], 'b', "Models simplify reality and are revised with new evidence."),
     ar("Colloidal particles can be seen with the naked eye.", "Colloids scatter a beam of light passing through them.", 'd', "A is false – colloidal particles are too small to be seen. R is true (Tyndall effect)."),
     sa("Why is a mixture of salt and water separated by evaporation, whereas a mixture of two miscible liquids is separated by distillation?", 2, "Salt is non-volatile, so water alone evaporates leaving the salt [1]; miscible liquids differ in boiling points, so the lower boiling one vaporises first and is condensed. [1]"),
     sa("4 g of hydrogen combines completely with 32 g of oxygen to form water. State the law and find the mass of water formed.", 2, "Law of conservation of mass – mass of products = mass of reactants [1]; water = 4 + 32 = 36 g [1]"),
     sa("Write the electronic configuration of sodium (atomic number 11). State its valency and give a reason.", 2, "2, 8, 1 [1]; valency 1 – it can lose its single outer electron to attain a stable octet. [1]"),
     sa("25 g of sugar is dissolved in 225 g of water. (i) Calculate the % m/m of the solution. (ii) How much water must be added to 100 g of this solution to reduce its concentration to 5 %?", 3, "(i) 25/250 × 100 = 10 % [1] (ii) Sugar in 100 g = 10 g; new mass = 10/0.05 = 200 g [1]; water to add = 100 g [1]"),
     OR(sa("How does fractional distillation differ from simple distillation? Give one example where it is used.", 3, "Simple: liquids with large bp difference; Fractional: uses a fractionating column for liquids with close bps [2]. Example: separation of gases of air / crude oil fractions. [1]"),
        sa("Why is crystallisation preferred to evaporation to dryness for purifying a solid? Give one example.", 3, "Evaporation to dryness may decompose/ char the solid and leaves soluble impurities in the residue [1½]; crystallisation gives pure, regular crystals as impurities stay in the solution [1]. Example: copper sulphate/alum/sugar [½]")),
     case("A student prepared three sugar solutions of different concentrations at room temperature, as shown in the table.<br>" + table(['Beaker', 'Sugar (g)', 'Water (g)'], [['P', '5', '95'], ['Q', '10', '90'], ['R', '20', '80']]) + "<br>(Solubility of sugar at room temperature ≈ 200 g per 100 g water.)",
          [sub("Which beaker has the highest concentration (% m/m)?", 1, "R (20 %). [1]"),
           sub("Calculate the % m/m of beaker Q.", 1, "10/100 × 100 = 10 %. [1]"),
           OR(sub("Is the solution in beaker R saturated or unsaturated? Justify.", 2, "Unsaturated [1]; 20 g per 80 g water is far below the solubility limit (≈ 160 g per 80 g). [1]"),
              sub("How much sugar is present in 50 g of the solution of beaker R?", 2, "20 % of 50 g [1] = 10 g [1]"))], lab='alpha'),
     OR(sa("A kerosene–water mixture and an acetone–water mixture are to be separated. Name the technique for each, give the principle, and describe the procedure for the first.", 5, "Kerosene–water: separating funnel (immiscible liquids differ in density) [1½]; acetone–water: distillation (difference in bp) [1½]. Procedure: pour mixture into funnel, allow layers to settle, open stopcock to drain the lower (water) layer, close it when the interface reaches the stopcock; collect kerosene. [2]"),
        sa("(a) Differentiate between a solution, a suspension and a colloid on the basis of particle size, Tyndall effect and stability. (b) Why does milk not settle on standing?", 5, "(a) Solution: <1 nm, no Tyndall, stable; Colloid: 1–100 nm, shows Tyndall, stable; Suspension: >100 nm, shows Tyndall, settles. [3 × 1] (b) Colloidal particles are very small and keep moving (Brownian motion), hence do not settle. [2]")),
    ]
    phy = [
     mcq("A cyclist covers the first half of a distance at 10 m s<sup>−1</sup> and the second half at 15 m s<sup>−1</sup>. His average speed for the whole journey is:", ["12.5 m s<sup>−1</sup>", "12 m s<sup>−1</sup>", "13 m s<sup>−1</sup>", "25 m s<sup>−1</sup>"], 'b', "v = 2v₁v₂/(v₁+v₂) = 2×10×15/25 = 12 m s⁻¹."),
     mcq("The displacement–time graph of a body is shown. Its velocity between t = 0 and t = 4 s is:", ["5 m s<sup>−1</sup>", "20 m s<sup>−1</sup>", "0", "80 m s<sup>−1</sup>"], 'a', "Slope = 20 m / 4 s = 5 m s⁻¹.", fig=graph([(0, 0), (4, 20), (8, 20), (12, 0)], 12, 24, 't (s)', 'x (m)', 4, 4)),
     mcq("A 10 kg box is pushed by a horizontal force of 30 N but does not move. The force of friction acting on it is:", ["zero", "10 N", "30 N", "100 N"], 'c', "The box is in equilibrium, so static friction equals the applied force, 30 N."),
     mcq("A truck of mass 2000 kg moving at 5 m s<sup>−1</sup> and a car of mass 1000 kg moving at 10 m s<sup>−1</sup> are compared. Their momenta are:", ["greater for the truck", "greater for the car", "equal", "cannot be compared"], 'c', "Both: 2000×5 = 1000×10 = 10 000 kg m s⁻¹."),
     mcq("A body of mass 1 kg has a kinetic energy of 50 J. Its speed is:", ["5 m s<sup>−1</sup>", "10 m s<sup>−1</sup>", "25 m s<sup>−1</sup>", "50 m s<sup>−1</sup>"], 'b', "v = √(2E/m) = √100 = 10 m s⁻¹."),
     mcq("An echo is heard 2 s after a clap. If the speed of sound in air is 340 m s<sup>−1</sup>, the distance of the reflecting wall is:", ["170 m", "340 m", "680 m", "1360 m"], 'b', "d = vt/2 = 340 × 2 / 2 = 340 m."),
     ar("The area under a speed–time graph gives the acceleration of the body.", "The slope of a velocity–time graph gives the acceleration of the body.", 'd', "A is false – the area gives the distance. R is true."),
     sa("A constant force of 12 N acts on a 3 kg body initially at rest for 4 s. Find (i) its acceleration and (ii) its velocity at the end of 4 s.", 2, "(i) a = F/m = 12/3 = 4 m s⁻² [1] (ii) v = at = 16 m s⁻¹ [1]"),
     OR(sa("A person standing in a bus falls backward when the bus suddenly starts. Name the law that explains this and explain.", 2, "Newton’s first law (inertia of rest) [1]; the feet move with the bus but the upper body tends to remain at rest. [1]"),
        sa("Why is it harder to stop a loaded truck than an empty one moving at the same speed?", 2, "Loaded truck has greater mass, hence greater momentum (inertia) [1]; so a larger force/longer time is needed to stop it. [1]")),
     sa("A ship sends an ultrasonic pulse of frequency 30 kHz towards the sea floor and receives the echo after 0.8 s. If the speed of sound in sea water is 1500 m s<sup>−1</sup>, calculate (i) the depth of the sea and (ii) the wavelength of the pulse.", 3, "(i) d = vt/2 = 1500 × 0.8/2 = 600 m [1½] (ii) λ = v/f = 1500/30000 = 0.05 m [1½]"),
     case("On Sports Day, Rohit tried to push a 40 kg wooden box across the playground. The maximum static friction between the box and the ground is 120 N and the kinetic friction is 80 N.",
          [sub("What is the force of friction on the box when Rohit pushes with 100 N and the box does not move?", 1, "100 N (static friction equals the applied force). [1]"),
           sub("Rohit now pushes with 160 N and the box starts sliding. Calculate its acceleration.", 1, "a = (160 − 80)/40 = 2 m s⁻². [1]"),
           OR(sub("Why is kinetic friction less than maximum static friction?", 2, "Once the box moves, the surface irregularities do not get enough time to interlock [1]; hence less force is needed to keep it moving. [1]"),
              sub("Write two ways in which friction between two surfaces can be reduced.", 2, "Polishing/smoothening the surfaces; lubrication (oil/grease); using ball bearings/wheels. [Any two × 1]"))], lab='alpha'),
     OR(sa("A stone is dropped from the top of a tower and reaches the ground after 4 s (g = 10 m s<sup>−2</sup>). Find (i) its velocity on hitting the ground, (ii) the height of the tower, (iii) the distance fallen in the last second, (iv) the average velocity during the fall and (v) the momentum on hitting the ground if its mass is 0.5 kg.", 5, "(i) v = gt = 40 m s⁻¹ [1] (ii) h = ½gt² = 80 m [1] (iii) 80 − ½×10×9 = 35 m [1] (iv) 80/4 = 20 m s⁻¹ [1] (v) 0.5 × 40 = 20 kg m s⁻¹ [1]"),
        sa("A car of mass 1000 kg moving at 20 m s<sup>−1</sup> is brought to rest in 10 s by uniform braking. Calculate (i) its initial momentum, (ii) the retardation, (iii) the braking force, (iv) the distance travelled before stopping and (v) the work done by the braking force.", 5, "(i) 20 000 kg m s⁻¹ [1] (ii) 2 m s⁻² [1] (iii) 1000 × 2 = 2000 N [1] (iv) s = ½ × 20 × 10 = 100 m [1] (v) W = 2000 × 100 = 2 × 10⁵ J [1]")),
    ]
    science_paper(2, bio, chem, phy)
if __name__ == '__main__': run()
